import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const examples = new URL('../examples/ci-package/', import.meta.url);
// These expectations are committed input data written from the workflow's
// intended release policy, not results generated by the production matcher.
const cases = JSON.parse(readFileSync(new URL('expected.json', examples), 'utf8'));

for (const scenario of cases) {
  test(`CI package scenario: ${scenario.file} selects its declared release set`, () => {
    const result = spawnSync(process.execPath, ['cli.mjs', '--input', fileURLToPath(new URL(scenario.file, examples)), '--json'], {
      cwd: root, encoding: 'utf8', timeout: 30000,
    });
    assert.equal(result.status, 0, result.stderr || result.stdout);
    const data = JSON.parse(result.stdout);
    assert.equal(data.exit_code, 0);
    assert.deepEqual(data.selected, scenario.selected);
  });
  test(`CI package scenario: ${scenario.file} explains inclusion and rejection`, () => {
    const result = spawnSync(process.execPath, ['cli.mjs', 'explain', '--input', fileURLToPath(new URL(scenario.file, examples)), '--json'], {
      cwd: root, encoding: 'utf8', timeout: 30000,
    });
    assert.equal(result.status, 0, result.stderr || result.stdout);
    const data = JSON.parse(result.stdout);
    assert.deepEqual(data.selected, scenario.selected);
    for (const expected of scenario.decisions) {
      const actual = data.decisions.find(item => item.path === expected.path);
      assert.ok(actual, `Missing explanation for ${expected.path}`);
      for (const key of ['selected', 'included_by', 'excluded_by', 'reason']) {
        assert.deepEqual(actual[key], expected[key], `${expected.path} ${key}`);
      }
    }
  });
}

test('CI package runner works from outside the source directory', () => {
  const result = spawnSync(process.execPath, [fileURLToPath(new URL('run.mjs', examples))], {
    cwd: tmpdir(), encoding: 'utf8', timeout: 30000,
  });
  assert.equal(result.status, 0, result.stderr || result.stdout);
  assert.match(result.stdout, /Verified 3 scenarios against handwritten expected results/);
  for (const scenario of cases) assert.ok(result.stdout.includes(`PASS ${scenario.file}:`));
});
